{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "A tocotrienol-rich fraction of palm oil, a lipophilic isoprenoid with a polar chromanol head, is reported to have poor oral bioavailability in humans, supporting low absorption for the structurally related lipophilic isoprenoid CoQ10.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed only 0.17% systemic appearance after oral intake in humans, illustrating that large lipophilic isoprenoids can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, a smaller and more flexible C40 isoprenoid, showed 58.5% absolute bioavailability in humans; this is the strongest high-bioavailability counterexample, but its transferability to the larger, quinone-headed CoQ10 is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "CoQ10 is a large, highly lipophilic isoprenoid quinone with known poor oral absorption; the closest transferable experimental evidence (tocotrienol, lycopene systemic appearance) supports F < 20%, while the high phytoene value is less transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for CoQ10 is provided in the visible evidence.",
    "The high phytoene and labeled-lycopene absorption values are from compartmental modeling and may not translate to CoQ10 due to differences in molecular size, polarity, and formulation.",
    "Formulation-dependent absorption is a major confounder for lipophilic isoprenoids; the evidence does not specify a CoQ10 formulation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}
```

